+function targetedSavedUrlBuckets(store, pending) {
+  const exact = new Map(), path = new Map();
+  for (const tab of pending) {
+    if (!tab.pinned) continue;
+    const keys = urlKeys(tab.url || tab.pendingUrl || '');
+    exact.set(keys.exact, []);
+    path.set(keys.path, []);
+  }
+  const add = (entry, space) => {
+    const keys = urlKeys(entry.url);
+    const exactBucket = exact.get(keys.exact), pathBucket = path.get(keys.path);
+    if (!exactBucket && !pathBucket) return;
+    const match = { entry, space };
+    if (exactBucket) exactBucket.push(match);
+    if (pathBucket) pathBucket.push(match);
+  };
+  for (const entry of store.favorites) add(entry, null);
+  for (const space of store.spaces) {
+    for (const node of space.pinned) {
+      if (node.kind === 'folder') for (const entry of node.children) add(entry, space);
+      else add(node, space);
+    }
+  }
+  return { exact, path };
+}
+
+function targetedSavedMatches(buckets, url, exclude) {
+  const keys = urlKeys(url);
+  const exact = (buckets.exact.get(keys.exact) || []).filter(({ entry }) => !exclude.has(entry.id));
+  return exact.length ? exact : (buckets.path.get(keys.path) || []).filter(({ entry }) => !exclude.has(entry.id));
+}
